quests[3882] = { id = 3882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenklappern", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marschalls Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodonten und Dimetrodonten graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", sourceObjective = "Bringt 8 Dinosaurierknochen zu Funks Nilminer im Krater von Un'Goro.", sourceObjectiveStatus = "unverified-source-field" }
quests[3883] = { id = 3883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fremdartige Ökologie", description = "Nur weil wir einen Rückschlag erlitten haben, heißt das noch lange nicht, dass unsere Forschungen ein Ende finden müssen! Bevor wir hier gelandet sind, untersuchten wir die Schwarmbauten der Gorishiinsekten im südlichen Teil des Kraters. Sie sind fremdartig und passen nicht zur ursprünglichen Ökologie des Un'Goro und wir wollen herausfinden, warum das so ist.\n\nIn ihrem Schwarmbauverbund muss es Larvenbrutstätten geben. Ihr könnt diesen Ort an der hängenden Raupenbrut erkennen. Hier, nehmt mit dieser Phiole eine Probe von der Schwarmbauwand in der Nähe der Brutstätten. Bringt sie dann zu mir zurück, damit ich sie untersuchen kann, aber seid vorsichtig!", sourceObjective = "Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Krater von Un'Goro zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.\n\nBringt die Schwarmbauwandprobe zu Hol'anyee Marschall im Krater von Un'Goro.", sourceObjectiveStatus = "unverified-source-field" }
quests[3884] = { id = 3884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willidens Tagebuch", description = "Ihr habt ein zerfleddertes Tagebuch zu Tage gefördert. Ein Teil davon ist noch lesbar; es scheint von einem gewissen Williden Marschall verfasst worden zu sein. Wenn das Tagebuch stimmt, dann muss Williden irgendwo im nördlichen Teil des Kraters zu finden sein. Dem Tagebuch zufolge haben er und seine Gefährten in den höheren Lagen des Kraters Schutz gesucht, nachdem ihre tiefer gelegenen Stützpunkte von den wilden Bestien überrannt wurden.", sourceObjective = "Bringt das Tagebuch zu Williden Marschall zurück. Er befindet sich irgendwo im Krater von Un'Goro.", sourceObjectiveStatus = "unverified-source-field" }
quests[3901] = { id = 3901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling the Rattlecages" }
quests[3902] = { id = 3902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenging Deathknell" }
quests[3903] = { id = 3903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milly Geltmark", description = "Ihr habt Euch als verlässlich erwiesen, {name}. Verlässlich und ohne Angst, Euch auch mal die Hände schmutzig zu machen, wie?\n\nTja, eine Freundin von mir, Milly Geltmark, hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Ich bin mir sicher, sie könnte Eure Hilfe gut gebrauchen.", sourceObjective = "Sprecht mit Milly Geltmark.", sourceObjectiveStatus = "unverified-source-field" }
quests[3904] = { id = 3904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Millys Ernte", description = "Eine Bande von Briganten, die Defias, sind in das Weingut von Nordhain eingedrungen, als ich gerade bei der Weinlese war! Ich habe es den Wachen von Nordhain gemeldet und sie haben mir auch versprochen, dass sie sich darum kümmern würden, aber... Ich habe Angst um meine Traubenernte! Selbst wenn die Defias sie nicht stehlen, befürchte ich, dass unsere Wachen beim Vertreiben der Rohlinge alles zertrampeln.\n\nBitte, Ihr müsst mir helfen! Die meisten Trauben sind schon in Eimern gesammelt, aber ich habe sie bei den Weinstöcken im Südosten zurückgelassen.\n\nBringt mir diese Kübel! Rettet meine Ernte!", sourceObjective = "Bringt 8 Kisten mit Millys Ernte zu Milly Geltmark in der Nähe der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3905] = { id = 3905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traubenliste", description = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.\n\nIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.", sourceObjective = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3906] = { id = 3906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmonie der Flamme", description = "Die Ältesten haben eine Störung der Elemente gespürt. Die Dunkeleisenzwerge haben einen üblen Geist in unsere Welt beschworen, durch den unser Land von einer ewigen Dürre heimgesucht werden könnte. Die Disharmonie der Flamme muss untersucht werden.\n\nBegebt Euch zum Schwarzfels und dann durch die Flammenschlucht in den Steinbruch. Dort werdet Ihr diesen Herrn des Feuers finden: Übermeister Pyron.\n\nMacht der Störung ein Ende und kehrt dann zu mir zurück.", sourceObjective = "Reist zum Steinbruch im Schwarzfels und tötet Übermeister Pyron. Kehrt zu Donnerherz zurück, sobald Ihr den Auftrag erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3907] = { id = 3907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmonie des Feuers", description = "Ich kann die Verderbtheit in der Luft, die Euch umgibt, riechen, {name}. Es gibt einen anderen, versteckt in den Tiefen des Schwarzfels, der diese Verderbtheit kontrolliert.\n\nDer Wind und die Erde schreien seinen Namen hinaus: Lord Incendius. Doch irgendjemand...irgendetwas...gebietet über dieses Wesen. Er ist nichts weiter als ein Abgesandter.\n\nSucht ihn und findet heraus, wo sich sein Meister versteckt hält. Kehrt zu mir zurück, sobald Ihr diese Information gesammelt habt.", sourceObjective = "Betretet die Schwarzfelstiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Donnerherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[3908] = { id = 3908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist für jeden ein Geheimnis", description = "Seht, ich habe keine Ahnung, wie ich hierher kam. Niemand weiß das - niemand versteht es! Ich kann mich einfach an nichts erinnern...\n\nAber diese Gegenstände, die Ihr mir gebracht habt... Ich erinnere mich an etwas.\n\nMein Schwert. Ich soll es irgendwie stärken, aber ich weiß beim besten Willen nicht, warum. Es tut mir leid, dass ich Euch nicht mehr sagen kann, aber ich kann mich einfach nicht erinnern!\n\nNa, egal, ich weiß aber, wo Ihr es hinbringen könnt: zu Donova Schneeweh in Winterquell. Ihr findet sie bei den Thermalquellen. Sie kann das Schwert an den Teichen dort aushärten.", sourceObjective = "Bringt Linkens Schwert zu Donova Schneeweh in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[3909] = { id = 3909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Videre-Elixier", description = "Was sagt Ihr da? Linken... HAT ES VERGESSEN?\n\nAh, verstehe... Hat sein Gedächtnis verloren...\n\nNa gut, hier ist sein Schwert. Es ist aber noch nicht fertig. Ich habe von jemandem gehört, der es fertig stellen kann, aber... tja, es könnte etwas schwierig werden, mit ihm zu reden.\n\nHört mal, ich weiß jemanden, der Euch bestimmt helfen kann. Ich kann Euch jetzt nicht alles erklären, das würde zu lange dauern, aber Ihr müsst Euch irgendwie ein Videre-Elixier beschaffen. Der Einzige, von dem ich weiß, dass er Euch dabei helfen kann, ist Gregan Hopfenspei. Er ist ziemlich schwer aufzuspüren, aber zuletzt hatte er ein Lager in der Wildnis von Feralas.", sourceObjective = "Sucht nach Gregan Hopfenspei im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Schneeweh nach Winterquell zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3911] = { id = 3911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Element", description = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, {name}.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hin gemurmelt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3912] = { id = 3912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Grab", description = "Durch dieses Elixier könnt Ihr mit jemandem sprechen, den Ihr normalerweise nicht einmal sehen würdet...\n\nBringt das Videre-Elixier und Linkens Schwert mit zum Friedhof kurz vor Gadgetzan in Tanaris. Wenn Ihr dort seid, nehmt den Trank zu Euch. Ihr werdet möglicherweise von der Wirkung sehr überrascht sein, aber erschreckt nicht.\n\nGeht in Eurer 'anderen Form' nach Norden, bis Ihr die Berge erreicht. Dort findet Ihr den, mit dem Ihr sprechen müsst, in einer der Felsspalten. Sein Name ist Gaeriyan.\n\nAber vergesst nicht: Nur in dieser Form wird er mit Euch sprechen...", sourceObjective = "Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[3913] = { id = 3913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabesstille", description = "Wenn Ihr zum Friedhof zurückkehrt, {name}, findet Ihr dort einen Grabstein... Nicht einfach nur irgendeinen Grabstein... Dieser hebt sich von all den anderen ab. Geheimnisse liegen darin verborgen.\n\nDrückt gegen den Stein, dann erfahrt Ihr von diesen Geheimnissen...", sourceObjective = "Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3914] = { id = 3914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linkens Schwert", description = "Ein greller Lichtblitz blendet Euch, dann könnt Ihr das Schwert wieder aufheben. Es hat sich verwandelt!", sourceObjective = "Liefert Linkens überragendes Schwert bei Linken im Krater von Un'Goro ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[3921] = { id = 3921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenikee Boltbucket" }
quests[3922] = { id = 3922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schraubnieten", description = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Schraubnieten mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.\n\nDer nächstgelegene Ort, an dem man sie bekommen kann, ist die in der Nähe befindliche Forschungsstation und das Schlickmoor im Osten. Die Leute von der Venture Company bewahren sie normalerweise in ihren Werkzeugkisten auf. Schaut in den Werkzeugkisten an beiden Orten nach und kommt zu mir zurück, sobald Ihr genug Schraubnieten gesammelt habt.", sourceObjective = "Sammelt 10 Schraubnieten aus den Werkzeugkisten rund ums Schlickmoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[3923] = { id = 3923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rilli Schmierklump", description = "Tja, das hat schon mal nicht funktioniert. Ich habe an dem Samophlang ein paar zusätzliche Messgeräte angebracht, um seine strukturelle Integrität zu messen, und laut der Anzeige war die Integrität am absoluten Tiefpunkt. Ich könnte natürlich noch ein paar Skalen und vielleicht auch den einen oder anderen Hebel anbringen, aber...ich glaube, das würde alles nur noch schlimmer machen.\n\nIhr solltet das Samophlang zu Rilli Schmierklump bringen. Er hat mal für die Venture Company gearbeitet. Wenn irgendjemand weiß, wie man das Ding reparieren kann, dann Rilli.\n\nIhr findet ihn bei 'Noggs Meistermaschinen' in Orgrimmar, im Tal der Ehre.", sourceObjective = "Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Schmierklump.", sourceObjectiveStatus = "unverified-source-field" }
quests[3924] = { id = 3924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlanghandbuch", description = "Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch. Als ich noch für die Venture Company arbeitete, hatte ich einen Konkurrenten, Boss Kupferdraht. Der hat das Geheimnis des Samophlangs gehütet wie seinen Augapfel und immer nur kleine Fitzelchen an Informationen an diejenigen verteilt, denen er traute. Zu dieser kleinen, ausgewählten Gruppe habe ich leider nicht gehört...\n\nBoss Kupferdraht war früher immer in der Felsadermine im Nordosten des Brachlandes. Beschafft Euch das Handbuch von ihm, und falls er irgendjemandem einzelne Seiten davon gegeben hat, dann müsst Ihr diese ebenfalls einsammeln.", sourceObjective = "Bringt das Samophlanghandbuch nach Orgrimmar zu Rilli Schmierklump.", sourceObjectiveStatus = "unverified-source-field" }
quests[3941] = { id = 3941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe des Gnoms", description = "Ich denke... Ich denke... Ich weiß, dass ich aus irgendeinem wichtigen Grund hergekommen bin...\n\nIch hab da eine Idee, {name}. In der Höhle dort drüben wohnt eine Gnomin namens J.D. Sie war sehr freundlich zu mir, als ich hier ankam. Vielleicht habe ich in meiner Verwirrung ihr gegenüber irgendwas erwähnt.\n\nWarum fragt Ihr sie nicht, ob sie etwas weiß? Oh, aber seid vorsichtig: Sie spielt immer mit diesen verrückten, leuchtenden Kristallen herum, die ich im Krater gesehen habe. Ich habe keine Ahnung, was sie da drinnen treibt.", sourceObjective = "Sucht J.D. Collie in der Höhle in Marschalls Zuflucht auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[3942] = { id = 3942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linkens Andenken", description = "Oh... Linken? Jaaa, der ist echt witzig. Als er hier ankam, murmelte er ständig irgendwelche seltsamen Dinge. Hat wahrscheinlich einen ziemlich heftigen Schlag auf den Kopf bekommen, würde ich mal sagen.\n\nAber etwas, das er gesagt hat, ist bei mir irgendwie hängen geblieben - dass er dabei war, eine Art Totem herzustellen; er sagte, er müsse mit jemandem namens Eridan Blauwind sprechen... an einem Ort namens Teufelswald, glaube ich.\n\nAber ich bezweifle, dass Linken Euch jetzt noch viel darüber sagen kann. Wenn Ihr mehr wissen wollt, solltet Ihr diesen Eridan vielleicht selbst suchen gehen...", sourceObjective = "Sucht Eridan Blauwind im südlichen Teil des Teufelswalds.", sourceObjectiveStatus = "unverified-source-field" }
quests[3961] = { id = 3961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linkens Abenteuer", description = "Wenn man sich überlegt, dass Linken nur hergekommen ist, um uns von Sturmflamme zu befreien... Er scheint so gar nichts Außergewöhnliches an sich zu haben, aber mir ist aufgefallen, dass er sich überhaupt nicht für meine Experimente oder Geräte interessiert hat, wie das bei den meisten Gnomen sonst der Fall ist. Er muss im Herzen ein echter Krieger sein.\n\nBringt ihm das Totem. Vielleicht hilft ihm das, sich zu erinnern, warum er hergekommen ist.", sourceObjective = "Bringt das Silbertotem von Aquementas zu Linken in Marschalls Zuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3962] = { id = 3962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allein ist es gefährlich", description = "{name}, ich fange endlich an, mich zu erinnern! Ich bin hergekommen, um gegen Sturmflamme zu kämpfen. Ich war auf einer Reise und das hätte der letzte Schritt sein sollen.\n\nAber ich bin kein Held mehr... sondern Ihr. Alles, was Ihr getan habt... Ihr müsst dies jetzt zu Ende bringen, nicht ich.\n\nFindet Sturmflamme und besiegt ihn. Er bewacht ein Artefakt, das die Goldene Flamme genannt wird. Es verleiht mehr Macht als alles, was ich je zuvor gesehen habe, und in den Händen von jemandem, dessen Herz böse ist, ist es äußerst gefährlich.\n\nIhr solltet aber unbedingt Verstärkung mitnehmen - es ist gefährlich, allein zu gehen.", sourceObjective = "Begebt Euch zum Feuersäulengrat südlich von Marschalls Zuflucht.\n\nSucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[3981] = { id = 3981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Gor'shak", description = "Der arme Gargal... er wurde davon völlig überrascht. BUMM! Der tödliche Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt...\n\n<Galamav zieht eine Grimasse.>\n\nAls wir den Pfeil herauszogen, sahen wir, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines Orcs hinter Gittern mit der Unterschrift von Commander Gor'shak.\n\nFalls er noch am Leben sein sollte, dort unten in den Tiefen, dann müsst Ihr ihn finden.\n\nEine Falle, sagt Ihr? Ach nee, Dumpfhuf! Deswegen geht ja auch Ihr und nicht wir!", sourceObjective = "Sucht Kommandant Gor'shak in den Schwarzfelstiefen.\n\nIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3982] = { id = 3982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los?", description = "Ich wurde unter der Schirmherrschaft von Thrall hierher geschickt. Glaubt Ihr wirklich, diese Clowns könnten mich fangen? Ich habe mich fangen lassen, um so Informationen sammeln zu können.\n\n<Gor'shak flüstert.>\n\nDie Prinzessin von Eisenschmiede wurde von Imperator Thaurissan entführt. Prinzessin Bronzebart befindet sich in dieser Stadt! Ich wette, dem alten Magni ist fast das Herz stehen geblieben, als er diese Neuigkeiten gehört hat.\n\n<Gor'shak lacht.>\n\nPssst! Hört Ihr das? Es kommen Wachen! VERTEIDIGT EUCH!", sourceObjective = "Verteidigt Gor'shak.", sourceObjectiveStatus = "unverified-source-field" }
quests[4001] = { id = 4001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los?", description = "Bisher war meine Kommunikation mit dem Zwerg Kharan in der Zelle auf der anderen Seite der Halle nur sehr eingeschränkt möglich. Doch ich konnte ihn immerhin davon überzeugen, dass ich - oder besser - dass wir ihm nichts Böses wollen.\n\nGeht und redet mit ihm und erfahrt so viel über die Prinzessin und ihre Entführer wie nur möglich. Bringt diese Informationen dann dem Kriegshäuptling.\n\nThrall will nicht, dass der Prinzessin ein Leid geschieht. Er hat irgendeinen großen Plan, und der umfasst auch, dass sie wieder sicher nach Eisenschmiede zurückgebracht wird. Kharan weiß das alles schon...Geht!", sourceObjective = "Sprecht mit Kharan Hammermacht und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebart. Bringt diese Informationen dann zu Thrall nach Orgrimmar.\n\nIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[4002] = { id = 4002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Östlichen Königreiche", description = "Ihr bringt ganz ausgezeichnete Nachrichten, {name}.\n\nAls Kriegshäuptling ist es meine Aufgabe, das zu tun, was das Beste für die Horde ist. Zu garantieren, dass die nachfolgenden Generationen nicht in einer hoffnungslosen Existenz gefangen sein werden.\n\nJetzt ist uns die einzigartige Chance, die Allianzen der Zukunft zu formen, in den Schoß gefallen. Wenn wir jetzt den Zwergen helfen, könnte dies unsere Beziehungen zu den Östlichen Königreichen enorm verbessern. Und aus genau diesem Grund dürft Ihr nicht versagen!\n\nSeid Ihr bereit?", sourceObjective = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4003] = { id = 4003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die königliche Rettung", description = "Der Schlag gegen die Dunkeleisenzwerge wird, wenn er denn erfolgreich verläuft, eine Schockwelle durch ihr ganzes Königreich jagen.\n\nPrinzessin Bronzebart ist unter der Kontrolle von Imperator Thaurissan. Um sie zu befreien, müsst Ihr den Imperator töten. Doch seid gewarnt, denn Eure Aufgabe ist doppelt gefährlich. Zweifellos wird Euch Prinzessin Bronzebart angreifen, solange sie noch der Kontrolle des Imperators unterliegt.\n\nIHR DÜRFT IHR KEIN LEID ZUFÜGEN!", sourceObjective = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebart von seinem bösen Zauber.", sourceObjectiveStatus = "unverified-source-field" }
quests[4004] = { id = 4004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist die Prinzessin gerettet?", description = "Ihr habt meinen Ehemann erschlagen, {race}! Mein Kind wird ohne Vater in diese Welt geboren werden.\n\n<Prinzessin Moira zeigt direkt auf Euch.>\n\nIch versichere Euch, dieses Kind wird der nächste Herrscher des Königreichs von Eisenschmiede sein. Ihr und Eure Art solltet für diese ungerechte Tat bis ans Ende aller Tage gejagt werden.\n\n<Ihr denkt, dass Prinzessin Moira vielleicht unter den Nachwirkungen von Thaurissans Zauber leidet.>\n\nLasst mich in Ruhe, {race}. Ich bin sicher, Euer Kriegshäuptling ist erpicht darauf, vom Ergebnis seiner Einmischung zu erfahren.", sourceObjective = "Kehrt zu Thrall in der Feste Grommash in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4005] = { id = 4005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquementas", description = "Nehmt diese Tasche mit Vorräten mit Euch nach Tanaris. Begebt Euch zur Mast- und Schotbucht und sucht dort einen Kreis aus Steinen.\n\nIn der östlichsten Halbinsel liegt das Geheimnis...\n\nLest aus dem Buch von Aquor vor - aber nur innerhalb dieses Kreises - und beschwört das einzige Wesen, das die Gegenstände, die Ihr gesammelt habt, in ein Totem verwandeln kann, mit dem Ihr Sturmflamme bekämpfen könnt.\n\nEs wird Aquementas nicht gefallen, dass Ihr ihn aufweckt, doch vergesst nicht: Ihr müsst unbedingt in dem Kreis bleiben, damit er die Gegenstände transformieren kann.", sourceObjective = "Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.\n\nBenutzt das Buch von Aquor, um Aquementas zu beschwören.\n\nWenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marschalls Zuflucht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4021] = { id = 4021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenangriff!", description = "Die Horde lobt Euch für Eure Erfolge gegen die Kolkar, doch die Kolkar kochen vor Wut. Ich habe Berichte erhalten, denen zufolge ein Kontingent Kolkar ihr Zuhause in Desolace verlassen hat und ins Brachland gezogen ist, um dort Rache zu üben. Den letzten Berichten nach, rücken Sie in diesem Moment von Westen her gegen diese Bunker vor!\n\nStellt Euch den Eindringlingen der Kolkar und bereitet der Bedrohung, die sie für das Brachland darstellen, ein Ende. Tötet sie, bis ihr Anführer, Kriegsherr Krom'zar, erscheint. Besiegt ihn und bringt mir ein Teil seiner Flagge als Beweis.\n\nWir zählen auf Euch, {name}.", sourceObjective = "Tötet Kolkarzentauren bis Krom'zar auftaucht, dann tötet ihn und nehmt einen Teil von Krom'zars Flagge an Euch.", progress = "Habt Ihr die Flagge?", completion = "Ihr habt es geschafft! Ihr habt die Kolkar besiegt!\n\nIch werde dafür sorgen, dass Thrall von Euren Taten hier erfährt, {name}.\n\nSchreitet erhobenen Hauptes dahin. Ihr und die Horde könnt stolz auf Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[4022] = { id = 4022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe der Flamme", description = "Der Klan ist sich Eurer Arbeit in der Sengenden Schlucht bewusst.\n\nZeigt sie mir, {race}. Die abgestreifte Drachenhaut, Dummkopf!", sourceObjective = "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windklinge erhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4023] = { id = 4023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe der Flamme", description = "Ihr sucht nach dem Klan? Zeigt mir einen Beweis für Eure Nützlichkeit, sterbliches Wesen.", sourceObjective = "Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.\n\nIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[4024] = { id = 4024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe der Flamme", description = "Ich möchte die sengenden Flammen des Feuerberges schmecken. Die flüssigen Feuer des Schwarzfels über mich strömen lassen. Diese Essenz, diese sengende Hitze ist es, nach der ich mich sehne.\n\nIn den Tiefen des Schwarzfels haust Bael'Gar: ein Wesen aus reinstem Feuer, geboren aus den Flammen des Ragnaros. Tötet Bael'Gar und bringt mir aus seinen glimmenden Überresten einen Teil seines inneren Feuers.\n\nVerwendet die Drachenhaut für seine Überreste, um die innere Flamme sicher entnehmen zu können.\n\nSeid erfolgreich und Ihr werdet belohnt.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und tötet Bael'Gar.\n\nIhr wisst lediglich, dass der Riese irgendwo in den Schwarzfelstiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\n\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4041] = { id = 4041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Videre-Elixier" }
quests[4061] = { id = 4061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Maschinen", description = "Wir stießen bereits bei unseren ersten Streifzügen in der Sengenden Schlucht auf die Maschinen. Weitere Nachforschungen ergaben, dass sie aus der Brennenden Steppe, eventuell auch aus den Schwarzfelstiefen, stammen. Und dafür brauchen wir Euch, {name}.\n\nEure erste Aufgabe besteht darin, Euch in die Brennende Steppe zu begeben und dort einige Elementarsplitter von den Felsautomatons und den geringen Felsgeschöpfen der Gegend zu beschaffen. Sobald Ihr eine ausreichende Menge gesammelt habt, kehrt zu mir zurück, dann werde ich herausfinden, woher sie wirklich stammen.", sourceObjective = "Begebt Euch in die Brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\n\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.", sourceObjectiveStatus = "unverified-source-field" }
quests[4062] = { id = 4062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Maschinen", description = "G.L.A.\n\nDas sind die Buchstaben, die in die Elementarsplitter eingeprägt sind. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen, die Ihr in der Brennenden Steppe zerstört habt, hatten den 'Rang IV'. Ich nehme an, das ist ein eher niedriger Rang.\n\nBringt diese Splitterprobe in das Lager im Osten zu Lotwil Veriatus. Er ist ein Gelehrter und vor allem für seine Arbeit auf dem Gebiet der Elementarforschung bekannt. Vielleicht kann er uns bei unserer Suche helfen.", sourceObjective = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\n\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[4063] = { id = 4063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Maschinen", description = "Das kann doch nicht Argelmach sein... Argelmach wurde vor zehn Jahren getötet. Warum ich das so genau weiß? Weil ich derjenige war, der ihn getötet hat.\n\nEr war ein abscheulicher Zwerg und wild entschlossen, mein Lebenswerk zu verderben und es für seine teuflischen Zwecke zu benutzen. Wie es scheint, finden die Tückischen immer einen Weg, ihrer gerechten Strafe zu entgehen.\n\nWenn dies Argelmachs Werk ist, dann muss er zerstört werden. Ich brauche Proben seiner jüngsten Schöpfungen. Mit den richtigen Proben kann ich vielleicht diesem Aufstand ein Ende machen. Die Schöpfungen bewachen Argelmach in den Schwarzfelstiefen.", sourceObjective = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4081] = { id = 4081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SOFORT TÖTEN: Dunkeleisenzwerge", description = "Auf Befehl von Kriegsherr Bluthauer, Kommandant des Expeditionskorps von Kargath:\n\nAlle Streitkräfte, über die General Zornesschmied in den Schwarzfelstiefen verfügt, müssen ausgelöscht werden.\n\nZornesschmieds Männer sind rücksichtslose Killer und verantwortlich für den Massenmord an der 109. Division des Expeditionskorps von Kargath. Alle Helden, die diesen gefühllosen Bestien gegenübertreten wollen, werden aufgefordert, extreme Vorsicht walten zu lassen.\n\nJede Person, die die erste Kampfreihe von General Zornesschmieds Streitkräften in den Schwarzfelstiefen vernichtet, wird einen Tribut erhalten.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Bluthauer möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4082] = { id = 4082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", description = "Auf Befehl von Kriegsherr Bluthauer, Kommandant des Expeditionskorps von Kargath:\n\nDer Leiter der Aufklärungseinheit des KEK, Großmeister Lexlort, kam mit Neuigkeiten über den Verbleib einiger hochrangiger Führungskräfte der Dunkeleisenzwerge zurück. Hinter dem verschlossenen Tor, nahe dem Herzen der Stadt, bilden sie ihre Streitkräfte darin aus, unsere Männer auszulöschen. Geht in die Schwarzfelstiefen und vernichtet sie!\n\nWer diese Mission erfüllt, erhält einen Tribut.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Bluthauer möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4083] = { id = 4083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der spektrale Kelch", progress = "Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens.", completion = "Geräuschlos fallen die Edelsteine in die Tiefen des Kelchs..." }
quests[4084] = { id = 4084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silberherz", description = "Ich kenne denjenigen nicht, von dem Ihr sprecht, {name}.\n\nDoch keine Sorge, wenn Euer Freund auf der Suche nach mir war, dann weiß ich, was er von mir wollte.\n\nIm Herzen des Kraters von Un'Goro lebt das Böse in seiner reinsten Form. Dort manifestiert es sich in der Gestalt eines Elementars namens Sturmflamme. Er wird von einer Aura beschützt, die niemand durchdringen kann.\n\nNiemand... außer denen, die über genügend Macht verfügen. Diese Macht kann ich Euch lehren, {name}.\n\nDoch zunächst müsst Ihr mir eine Bitte erfüllen. Beschafft 11 silbrige Klauen und 1 Eisenstammherz von den Kreaturen im Teufelswald und kommt dann zu mir zurück.", sourceObjective = "Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Blauwind im Teufelswald.", sourceObjectiveStatus = "unverified-source-field" }
quests[4101] = { id = 4101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Teufelswald säubern", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", sourceObjective = "Bringt 15 Einheiten Blutharz zu Arathandris Silberwolke im Teufelswald.", sourceObjectiveStatus = "unverified-source-field" }
