quests[4401] = { id = 4401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume" }
quests[4402] = { id = 4402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgars Kaktusapfel Surprise", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweiß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, {name}. Wenn Ihr mir 6 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", sourceObjective = "Bringt Galgar 6 Kaktusäpfel. Ihr erinnert Euch doch, dass er gesagt hat, man fände sie in der Nähe von Kakteen?", sourceObjectiveStatus = "unverified-source-field" }
quests[4403] = { id = 4403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte" }
quests[4421] = { id = 4421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis der Jadefeuer", description = "Nicht viele kommen hierher und suchen das Abenteuer... Die Verderbnis hat sich im Teufelswald überall ausgebreitet und macht vor nichts Halt.\n\nAls Mitglied des Smaragdkreises trachte ich danach, dieses Land zu heilen. Doch es gibt andere, die wünschen, dass es weiter schwärt.\n\nIch spreche von den Jadefeuersatyrn, die sich nordwestlich von hier aufhalten, bei den Ruinen von Constellas. Ihr Anführer ist ein besonders grausamer Satyr namens Xavathras und unter seiner Führung übertragen sie die Krankheit auf alle Wesen, denen sie begegnen.\n\nWir müssen dieses Land, das einst das unsrige war, verteidigen. Besiegt Xavathras und vernichtet seine Diener.", sourceObjective = "Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Blauwind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[4441] = { id = 4441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebundene Urtume", description = "Die Flöte, die Ihr gefunden habt, wurde aus einem Urtumbeschützer geschnitzt, den Treantverbündeten, die schon immer treu über die Nachtelfen gewacht haben.\n\nEs ist den Satyrn gelungen, alles zu verderben, mit dem sie in Kontakt kommen, einschließlich der Urtume, die im Teufelswald lebten. Mithilfe der teuflischen Verderbnis wurde der Geist des Urtums gefangen und gefoltert und nie wieder völlig freigegeben. Der Teufelsbinder, den Ihr gefunden habt, hängt ganz ohne Zweifel damit zusammen.\n\nWir müssen versuchen, die Flöte zu läutern, {name}. Bringt mir gesegnetes Wasser vom Tempel des Mondes in Darnassus.", sourceObjective = "Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4442] = { id = 4442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geläutert!", description = "Ich werde jetzt versuchen, die Flöte mit dem Wasser von Elune zu läutern. Wir müssen diesem Leiden ein Ende machen...\n\nMöge Elune meine Hände und mein Herz leiten.\n\nSprecht mich gleich noch einmal an.", sourceObjective = "Sprecht Eridan gleich noch einmal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[4443] = { id = 4443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Peitscherwurzel" }
