quests[4447] = { id = 4447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Nachtdrache" }
quests[4448] = { id = 4448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Nachtdrache" }
quests[4449] = { id = 4449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingesperrt!", description = "He! He, Ihr da! Kommt her!\n\nIhr müsst mir dringend helfen. Ich bin vor den Dunkeleisenzwergen abgehauen und hab mich hier drin versteckt, damit se mich nich' sehen. Verdammte Drecksgeologen und ihre Magie! Die müss'n geseh'n haben, wie ich mich versteckt hab, weil als Allernächstes ham se die Tür versperrt. Ham was gesagt von wegen, dass sie zurückkommen und mich holen würden, und dann sind sie verschwunden.\n\nIhr müsst denen zeigen, wer hier der Boss ist! Könnt Ihr das für mich tun? Verpasst den Geologen 'ne Lektion! Ach, und könnt Ihr mir 'n paar Stücke Seidenstoff beschaffen für...für...ach, für nix.", sourceObjective = "Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der Sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", sourceObjectiveStatus = "unverified-source-field" }
quests[4450] = { id = 4450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschäftsbuch aus Tanaris", description = "Ach, wisst Ihr was? Da fällt mir grade was ein.\n\nWo ich doch immer noch hier drin festsitz: Wollt Ihr nich' vielleicht 'n kleinen Job für mich fertig machen, den ich angenommen hab, als ich in Tanaris war? Is' auch ganz einfach... na ja, wenn man nich' grade hier drin sitzt, jedenfalls.\n\nKrinkle Goldstahl in Gadgetzan war scharf auf so'n paar Sachen, die hier in der Sengenden Schlucht und an 'n paar anderen Orten gefunden wurden. Vielleicht könnt Ihr Euch ja die Liste einmal ansehen und ihm den Kram dann bringen?\n\nIch schieb Euch sein Geschäftsbuch unter der Tür durch, wenn Ihr interessiert seid. Bringt es ihm zusammen mit dem Zeug, das er will, nachdem Ihr den ganzen Kram eingesammelt habt.", sourceObjective = "Nehmt die Abschrift von Goldstahls Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goldstahl in Tanaris aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4451] = { id = 4451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zur Freiheit", description = "Der kleine Messingschlüssel sieht recht einfach aus. Das Einzige, was ihn von anderen seiner Art unterscheidet, sind einige Worte, die darauf eingeritzt sind:\n\n\"Dunkeleisenplumpsklo - Nicht duplizieren.\"\n\nIhr habt absolut keine Ahnung, was das heißen soll oder wofür der Schlüssel gut ist.", sourceObjective = "Sucht in der Sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel für Rußschlacks Schuppen verwenden kann, den Ihr gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4461] = { id = 4461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Peitscherwurzel" }
